4. Create a directory named `cypress` in your Cypress project root directory.

5. Inside the `cypress` directory, create a `support` folder.

6. Inside the `support` folder, create a `index.js` file with the following content:

```javascript
import allure from "allure-cypress";

Cypress.Commands.add("login", (username, password) => {
  cy.visit("/login");
  cy.get("[data-test=username]").type(username);
  cy.get("[data-test=password]").type(password);
  cy.get("[data-test=login-button]").click();
});

Cypress.Commands.add("captureScreenshot", (testCaseName) => {
  Cypress.runnerLog(`Capturing screenshot for ${testCaseName}`);
  Cypress.log({
    name: "captureScreenshot",
    message: testCaseName,
  });
  return Cypress.env("SCREENSHOT_FOLDER").then((folderPath) => {
