9. Inside the `cypress` directory, create a `plugins` folder.

10. Inside the `plugins` folder, create a `index.js` file with the following content:

```javascript
const fs = require("fs");
const path = require("path");
const { allure } = require("@wdio/allure-reporter");

module.exports = (on, config) => {
  on("task", {
    screenshot: (filePath) => {
      return new Promise((resolve, reject) => {
        Cypress.runnerLog(`Capturing screenshot: ${filePath}`);
        Cypress.log({
          name: "screenshot",
          message: filePath,
        });

        const screenshot = Cypress.base64EncodedScreenshots[0];

        fs.writeFile(filePath, Buffer.from(screenshot, "base64"), (err) => {
          if (err) {
            reject(err);
          } else {
            resolve({ path: filePath });
          }
        });
      });
    },
  });

  on("before:browser:launch", (browser, launchOptions) => {
    if (browser.name === "chrome" && launchOptions.args.length) {
      launchOptions.args.push("--disable-infobars");
    }

    if (browser.name === "chrome" || browser.name === "firefox") {
      launchOptions.args.push("--window-size=1920,1080");
    }

    return launchOptions;
  });

  config.videoFolder = path.join(config.projectRoot, "screenshots");

  fs.mkdirSync(config.videoFolder, { recursive: true });

  allure.setDefaultReporterOptions({
    reportTitle: "Cypress Allure Report",
    resultsFolderPattern: "cypress/reports",
    outputDirectory: "allure-results",
  });

  return config;
};
```

11. Inside the `cypress` directory, create a `integration` folder.

12. Inside the `integration` folder, create a `spec.js` file with the following content:

