13. Create a `user.json` file in the root directory of your Cypress project with the following content:

```json
{
  "username": "test_user",
  "password": "test_password"
}
```

14. Run the tests by executing the following command:

```
docker-compose up
```

The tests will run using Docker, and Cypress will capture screenshots for each test case and generate an Allure report with the screenshots included.

Note: This is just an example, and you may need to adjust the configuration based on your specific project requirements. Also, make sure to replace the `CYPRESS_baseUrl` environment variable with the correct URL for your application.

Here's an example implementation of a C++ function that converts a Markdown string to an HTML string:

```cpp
#include <string>
#include <iostream>
#include <regex>

// Function to convert Markdown to HTML
std::string convertMarkdownToHtml(const std::string& markdown) {
    // Define regular expressions for common Markdown formatting
    std::regex bold_regex("([^\\*]+)\\*([^\\*]+)\\*", std::regex::icase);
    std::regex italic_regex("([^_]+)_([^_]+)", std::regex::icase);
    std::regex link_regex("\\[([^\\[]*?)\\]\\([^\\)]*?)\\(([^\\)]*?)\\)", std::regex::icase);
    std::regex header_regex("(#{1,6})\\s+([^\\n]*)", std::regex::icase);
    std::regex blockquote_regex("^> (.*)", std::regex::icase);
    std::regex unordered_list_regex("^\\*+\\s+(.*)", std::regex::icase);
    std::regex ordered_list_regex("^\\d+\\.\\s+(.*)", std::regex::icase);
    std::regex code_block_regex("^```(\\w*)\\n((.|\n)*?)\\n```", std::regex::icase);

    // Define HTML tags and attributes
    const std::string bold_tag = "<strong>";
    const std::string italic_tag = "<em>";
    const std::string link_tag_open = "<a href=\"";
    const std::string link_tag_close = "</a>";
    const std::string header_tag_open = "<h";
    const std::string header_tag_close = "></h>";
    const std::string blockquote_tag = "<blockquote>";
    const std::string unordered_list_tag = "<ul>";
    const std::string ordered_list_tag = "<ol>";
    const std::string code_block_tag_open = "<pre><code class=\"";
    const std::string code_block_tag_close = "</code></pre>";

    std::string html;
    // Apply regular expressions and replace with corresponding HTML tags
    html = std::regex_replace(markdown, bold_regex, std::string(bold_tag) + "$2" + bold_tag);
    html = std::regex_replace(html, italic_regex, std::string(italic_tag) + "$2" + italic_tag);
    std::smatch link_match;
    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string link_text = link_match[1];
        std::string link_url = link_match[3];
        html += std::string(link_tag_open) + link_url + link_tag_close + link_text;
        markdown = link_match.suffix().str();
    }
    std::smatch header_match;
    while (std::regex_search(markdown, header_match, header_regex)) {
        std::string header_level = header_match[1];
        std::string header_text = header_match[2];
        html += std::string(header_tag_open) + header_level + header_text + header_tag_close;
        markdown = header_match.suffix().str();
    }
    std::smatch blockquote_match;
    while (std::regex_search(markdown, blockquote_match, blockquote_regex)) {
        std::string blockquote_text = blockquote_match[1];
        html += blockquote_tag + blockquote_text + blockquote_tag;
        markdown = blockquote_match.suffix().str();
    }
    std::smatch unordered_list_match;
    while (std::regex_search(markdown, unordered_list_match, unordered_list_regex)) {
        std::string list_items = unordered_list_match[1];
        html += unordered_list_tag + "\n<li>" + list_items + "</li>\n" + unordered_list_tag;
        markdown = unordered_list_match.suffix().str();
    }
    std::smatch ordered_list_match;
    while (std::regex_search(markdown, ordered_list_match, ordered_list_regex)) {
        std::string list_items = ordered_list_match[1];
        html += ordered_list_tag + "\n<li>" + list_items + "</li>\n" + ordered_list_tag;
        markdown = ordered_list_match.suffix().str();
    }
    std::smatch code_block_match;
    while (std::regex_search(markdown, code_block_match, code_block_regex)) {
        std::string language = code_block_match[1];
        std::string code = code_block_match[2];
        html += code_block_tag_open + language + ">" + code + "</" + code_block_tag_open.substr(0, code_block_tag_open.length() - 1);
        markdown = code_block_match.suffix().str();
    }

    // Return the resulting HTML string
    return html;
}

int main() {
    std::string markdown = "Hello, **world**! _This is a test._ [Google](https://www.google.com/) has a logo. # Header\n## Subheader\n### Subsubheader\n> This is a blockquote.\n\n* Item 1\n* Item 2\n1. Item 1\n2. Item 2\n\n```
This is a code block.
```";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This implementation uses regular expressions to match common Markdown formatting and replace them with corresponding HTML tags. Note that this is not a complete implementation of a Markdown parser and may not handle all possible edge cases or extensions. Additionally, the regular expressions may need to be updated to handle new versions of Markdown.

